INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(337, 'koKR', 'Oficjalne rozkazy dla floty Kul Tiras\n\nJa, admirał Proudmoore, poprowadzę pierwsze lądowanie na brzegach Kalimdoru.\n\nPod moją nieobecność zastępcą dowódcy będzie porucznik Benedict. To on zajmie się wszystkimi krajowymi sprawami wojskowymi Kul Tiras. Jeśli w ciągu 12 miesięcy nie przyślę wieści z Twierdzy Tiragarde, porucznik Benedict poprowadzi drugą falę, by utrzymać to miejsce.', 0),
(338, 'koKR', 'Tymczasem wysyłam porucznika Alverolda na misję zwiadowczą wokół kontynentu Kalimdor. Jego oddziały mają wykonać zadanie, a następnie dołączyć do naszych sił w Twierdzy Tiragarde.\n\nPrzewiduje się, że misja porucznika Alverolda potrwa dość długo. Nowy ląd wydaje się rozległy i niebezpieczny. Gdyby jednak mnie lub Benedicta spotkało nieszczęście, oddziały Alverolda odbiją Twierdzę.\n\nBędziemy posyłać falę za falą, dopóki ta twierdza nie będzie nasza!\n\n– Admirał Proudmoore', 0),
(340, 'koKR', '<HTML>\n<BODY>\n<H1>Formularz poboru do Hordy</H1>\n<BR></BR>\n<P>Ta osoba wykazała się niezwykłą siłą i umiejętnościami w imię Hordy. Należy ją natychmiast skierować do pracy na Rozdrożu.</P>\n<BR></BR>\n<BR></BR>\n<P>Z wyrazami szacunku:</P>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<P>Wszystko się zgadza.<BR></BR>\n– Takrin Poszukiwacz Dróg</P>\n</BODY>\n</HTML>', 0),
(341, 'koKR', '<HTML>\n<BODY>\n<H1>Formularz poboru do Hordy</H1>\n<BR></BR>\n<P>Ta osoba wykazała się niezwykłą siłą i umiejętnościami w imię Hordy. Należy ją natychmiast skierować do pracy na Rozdrożu.</P>\n<BR></BR>\n<BR></BR>\n<P>Z wyrazami szacunku:\n<BR></BR>– Kargal Blizna Wojny</P>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<P>Wszystko się zgadza.<BR></BR>\n– Takrin Poszukiwacz Dróg</P>\n</BODY>\n</HTML>', 0),
(410, 'koKR', '1. Złap człowieka. Albo ośmiu$B2. Walnij człowieka mocno$B3. Walnij człowieka jeszcze$B4. Wrzuć człowieka do ognia$B5. Zjedz człowieka', 0),
(752, 'koKR', 'Hej. Zanieś ten list Frangowi w Dolinie Prób. Zwykle stoi przed Norą i przysposabia młodych wojowników do walki za Hordę.$B$BPotrzebuje sprytnych wojowników takich jak ty, żeby pokazać orkom, jak walczyć czymś innym niż mięśniami. Jesteś $gszybszy i mądrzejszy:szybsza i mądrzejsza; od większości z nich, ale lepiej się tym nie chwal – orkowie nie znoszą obelg. To dobrzy sojusznicy i może też cię czegoś nauczą.$B$B– Tar\'sere', 0),
(2131, 'koKR', 'Throm-Ka, $gwojowniku:wojowniczko;. Nie będę się rozpływał nad twoimi czynami siły i męstwa. To stare dzieje. $GZabiłeś:Zabiłaś; ostatnio jakichś ludzi? Pewnie niewielu. Zwalniasz. Miękniesz bez wyzwań.\n\nPotrzebuję kolejnej pary rąk, a ty – cokolwiek mówią twoi lizusi – potrzebujesz szkolenia, które mogę ci dać. Kiedy wreszcie wbijesz to sobie do tego zakutego łba, będę czekał pod zadaszeniem tuż przed Norą.\n\n– Frang, nauczyciel wojowników', 0),
(2434, 'koKR', 'Przesyłam pozdrowienia, $N. Byłem pogrążony w myślach, gdy uświadomiłem sobie, że muszę do ciebie napisać.$B$BWielu w naszej kulturze wychwala szamanów jako naszych duchowych przywódców, tak jak naszego wielkiego wodza. Inni uważają miecz i topór za jeszcze szlachetniejsze zajęcia, ale nigdy nie zapominaj, że bitwy – a nawet wojny – wygrywa się dzięki tym, którzy mają bardziej wyspecjalizowane umiejętności. Właśnie o tym chcę z tobą pomówić, $N. Znajdź mnie w głębi Nory w Dolinie Prób.$B$B– Rwag, nauczyciel łotrów', 0),
(2438, 'koKR', 'Pozdrawiam cię, $gbracie:siostro;. Strzaskana Dłoń przesyła wyrazy szacunku i ma nadzieję, że Dolina okaże się dla ciebie wygodnym miejscem do uprawiania twojego fachu. To dla ciebie czas prób, więc nie myśl, że nikt cię nie obserwuje – obserwujemy cię nieustannie.$B$BMoim obowiązkiem jest ocenić twoje umiejętności dla Dłoni, a potem dać jej znać, gdy uznam, że jesteś $ggotów:gotowa; na większe wyzwania.$B$BGdy będziesz $ggotów:gotowa;, znajdź mnie w głębi Nory. Będę tam na ciebie czekał.$B$B– Rwag, nauczyciel łotrów', 0),
(2448, 'koKR', 'Witaj w swoim przebudzeniu. Tajemnice arkanów są w twoim zasięgu, jeśli masz dość siły, by je utrzymać.$B$BZnajdź Mai\'ah, gdy będziesz $ggotów:gotowa;. Nauczy cię wiele o magii i czarach, których potrzebujesz, by niszczyć tych, którzy staną ci na drodze.$B$BMai\'ah jest przy Norze w Dolinie Prób. Przyjdź, znajdź ją, a staniesz się $gsilny:silna;. A potem pokażesz innym magom, że to magia nagina się do twojej woli... a nie na odwrót.', 0),
(2451, 'koKR', 'Piszę tę wiadomość najpotężniejszym atramentem, jaki potrafię stworzyć, $N. Natychmiast przeklnie każdego, kto oprócz ciebie ośmieli się ją przeczytać. Tak wielka jest moja moc. Przyzywam demony z Wypaczonej Otchłani, kiedy tylko zechcę. Nękam wrogów we śnie i na polu bitwy. A teraz ty także $gujrzałeś:ujrzałaś; moc mojej ścieżki. Moi bracia są z tego zadowoleni.$B$BOdszukaj mnie w głębi Nory, gdy już się tu rozejrzysz. Chcę z tobą pomówić o ważnych sprawach.$B$B– Nartok, nauczyciel czarnoksiężników', 0),
(2454, 'koKR', 'Teraz jesteś w dobrych rękach. Jen\'shan wie, że chcesz poznać drogę łowcy, i jest gotowa cię uczyć... jeśli ty jesteś $ggotów:gotowa; słuchać.$B$BZnajdź mnie w Dolinie Prób. Jen\'shan zacznie twoje szkolenie i pokaże ci, jak potężna jest droga łowcy.$B$B– Jen\'shan, nauczycielka łowców', 0),
(2457, 'koKR', 'Dobrze słyszeć, że $gjeden z braci:jedna z sióstr; Jen\'shan przybywa do Doliny, by sprawdzić swoje umiejętności. Jen\'shan już nie może się doczekać!$B$BNie muszę ci mówić, jak $gsilnym i sprytnym łowcą:silną i sprytną łowczynią; jesteś – $gsam:sama; to wiesz. Zadaniem Jen\'shan jest pokazać ci, jak stać się $gjeszcze silniejszym i sprytniejszym:jeszcze silniejszą i sprytniejszą;.$B$BZnajdziesz Jen\'shan w Dolinie Prób. Dobrze cię wyszkoli. Nauczy cię oswajać największe bestie i wielu innych rzeczy.$B$B– Jen\'shan, nauczycielka łowców', 0),
(2461, 'koKR', 'Lok-tar, $gbracie:siostro;. Żywioły przyzywają cię bliżej i każą mi wskazać ci ścieżkę szamana. Duchy naszych przodków spoglądają z zaświatów i rosną w dumę, wiedząc, że $gdołączyłeś:dołączyłaś; do naszych szeregów.$B$BGdy będziesz $ggotów:gotowa;, odszukaj mnie przy wejściu do Nory. Tam będę szkolić innych z naszego ludu. Do tego czasu niech wiatr wieje ci w plecy.$B$BShikrik, nauczycielka szamanów', 0),
(2462, 'koKR', 'Pozdrawiam cię, $gbracie:siostro;. Duchy mówią, że jesteś $ggotów:gotowa; wspierać naszych sojuszników. Masz silną więź z żywiołami i jesteś o wiele $gpotężniejszy:potężniejsza; niż wtedy, gdy $gzaczynałeś:zaczynałaś; u mnie naukę.$B$BTeraz wysyłam cię na spotkanie z Shikrik, orczą nauczycielką szamanów w Dolinie Prób. Ona już wie, że przyjdziesz do niej na naukę. Przynieś chlubę naszym przodkom. Do następnego spotkania niech płomień cię grzeje, a wiatr wieje ci w plecy.$B$B– Ishi-yo', 0),
(2469, 'koKR', 'Mam nadzieję, że duchy dotąd cię chroniły. Czeka cię wiele prób, a ja chętnie podzielę się z tobą swoim doświadczeniem, kiedy będziesz $ggotów:gotowa;. Od ciebie zależy, jak szybko i jak bardzo urośniesz w siłę. Ja mogę cię tylko prowadzić, gdy będziesz $ggotów:gotowa;.$B$BDla niektórych to idzie naprawdę szybko, dla innych... nie tak prędko. Ale nie przejmuj się tym. Porozmawiamy więcej, gdy do mnie przyjdziesz.$B$B– Ken\'jai, nauczyciel kapłanów', 0);
